INDEX_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<link rel="icon" type="image/png" href="data:image/png;base64,">\n<meta property="og:type" content="website">\n<meta property="og:url" content="https://shieldlint.vercel.app/">\n<meta property="og:title" content="ShieldLint — the missing privacy diagnostic for Zcash">\n<meta property="og:description" content="Offline static analysis that finds transparent recipients, memo and viewing-key leaks, and broken ZIP 316 / ZIP 321 encodings before they ship.">\n<meta property="og:image" content="https://shieldlint.vercel.app/api/og">\n<meta property="og:image:width" content="1200">\n<meta property="og:image:height" content="630">\n<meta name="twitter:card" content="summary_large_image">\n<meta name="twitter:title" content="ShieldLint — the missing privacy diagnostic for Zcash">\n<meta name="twitter:description" content="14 rules, 70 tests, official Zcash test vectors. Scan, decode addresses and validate payment requests in the browser.">\n<meta name="twitter:image" content="https://shieldlint.vercel.app/api/og">\n<title>ShieldLint — Zcash privacy linter</title>\n<meta name="description" content="Offline static analysis that finds where a Zcash integration leaks money-flow metadata.">\n<style>\n  :root{\n    --bg:#080d0b; --panel:#0e1613; --panel-2:#111c17; --line:#1d2f27;\n    --text:#d7e5dd; --muted:#7a9087; --green:#4ade80; --green-dim:#1f6f45;\n    --red:#f87171; --amber:#fbbf24; --cyan:#67e8f9; --purple:#c084fc;\n    --mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;\n    --sans:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);\n       font-size:15px;line-height:1.55;-webkit-font-smoothing:antialiased}\n  a{color:var(--green);text-decoration:none}\n  a:hover{text-decoration:underline}\n  .wrap{max-width:1000px;margin:0 auto;padding:28px 22px 80px}\n  header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;flex-wrap:wrap}\n  .logo{display:flex;align-items:center;gap:12px}\n  .mark{width:34px;height:38px;flex:0 0 auto}\n  h1{font-family:var(--mono);font-size:26px;letter-spacing:-.5px;margin:0}\n  h1 span{color:var(--green)}\n  .tag{color:var(--muted);font-size:13.5px;margin:6px 0 0}\n  .nav{display:flex;gap:16px;font-family:var(--mono);font-size:12.5px;color:var(--muted);padding-top:6px}\n  .tabs{display:flex;gap:4px;margin:26px 0 18px;border-bottom:1px solid var(--line);flex-wrap:wrap}\n  .tab{background:none;border:0;border-bottom:2px solid transparent;color:var(--muted);\n       font-family:var(--mono);font-size:13px;padding:10px 14px;cursor:pointer;letter-spacing:.2px}\n  .tab:hover{color:var(--text)}\n  .tab[aria-selected="true"]{color:var(--green);border-bottom-color:var(--green)}\n  .panel{display:none}\n  .panel.on{display:block}\n  .card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:16px}\n  .row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n  label.field{display:block;font-family:var(--mono);font-size:11.5px;letter-spacing:.6px;\n               text-transform:uppercase;color:var(--muted);margin:0 0 6px}\n  input[type=text],textarea,select{\n    width:100%;background:#070c0a;color:var(--text);border:1px solid var(--line);\n    border-radius:8px;padding:11px 12px;font-family:var(--mono);font-size:12.5px;}\n  textarea{resize:vertical;line-height:1.5}\n  input:focus,textarea:focus,select:focus{outline:none;border-color:var(--green-dim);\n    box-shadow:0 0 0 3px rgba(74,222,128,.08)}\n  button.btn{background:var(--green);color:#04120a;border:0;border-radius:8px;\n    padding:10px 16px;font-family:var(--mono);font-size:12.5px;font-weight:600;cursor:pointer}\n  button.btn:hover{filter:brightness(1.08)}\n  button.ghost{background:transparent;color:var(--text);border:1px solid var(--line)}\n  button.ghost:hover{border-color:var(--green-dim);color:var(--green)}\n  .hint{color:var(--muted);font-size:12.5px;margin:8px 0 0}\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n  @media(max-width:760px){.grid2{grid-template-columns:1fr}}\n  .out{margin-top:16px}\n  .summary{display:flex;gap:10px;flex-wrap:wrap;font-family:var(--mono);font-size:12px;margin-bottom:14px}\n  .pill{border:1px solid var(--line);border-radius:999px;padding:4px 11px;color:var(--muted)}\n  .pill.err{color:var(--red);border-color:#4a1f1f}\n  .pill.warn{color:var(--amber);border-color:#4a3a1a}\n  .pill.ok{color:var(--green);border-color:var(--green-dim)}\n  .finding{background:var(--panel-2);border:1px solid var(--line);border-left:3px solid var(--amber);\n    border-radius:8px;padding:12px 14px;margin-bottom:10px}\n  .finding.error{border-left-color:var(--red)}\n  .fhead{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;font-family:var(--mono);font-size:12px}\n  .rid{color:var(--muted)}\n  .sev{text-transform:uppercase;letter-spacing:.6px;font-size:10.5px;font-weight:700}\n  .sev.error{color:var(--red)} .sev.warning{color:var(--amber)} .sev.note{color:var(--cyan)}\n  .ftitle{color:var(--text);font-weight:600;margin:6px 0 4px;font-size:14px}\n  .fdetail{color:var(--muted);font-size:13px}\n  .floc{color:var(--muted);font-family:var(--mono);font-size:11.5px;margin-top:8px}\n  .fhelp{font-family:var(--mono);font-size:11.5px;margin-top:6px}\n  code,kbd{font-family:var(--mono);font-size:.92em;background:#0a1410;border:1px solid var(--line);\n    border-radius:5px;padding:1px 5px;color:#bfe7d1}\n  .kv{display:grid;grid-template-columns:130px 1fr;gap:6px 14px;font-family:var(--mono);font-size:12.5px}\n  .kv dt{color:var(--muted)} .kv dd{margin:0;word-break:break-all}\n  .bad{color:var(--red)} .good{color:var(--green)} .warnc{color:var(--amber)}\n  ul.plain{margin:8px 0 0;padding-left:18px;color:var(--muted);font-size:13px}\n  .rule{background:var(--panel-2);border:1px solid var(--line);border-radius:8px;\n    padding:12px 14px;margin-bottom:10px}\n  .rule h3{font-family:var(--mono);font-size:13px;margin:0 0 6px;font-weight:600}\n  .rule p{margin:6px 0 0;color:var(--muted);font-size:13px}\n  .spin{display:inline-block;width:12px;height:12px;border:2px solid var(--line);\n    border-top-color:var(--green);border-radius:50%;animation:s .7s linear infinite;vertical-align:-2px}\n  @keyframes s{to{transform:rotate(360deg)}}\n  footer{margin-top:44px;border-top:1px solid var(--line);padding-top:16px;\n    color:var(--muted);font-size:12.5px;display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}\n  .banner{background:linear-gradient(90deg,rgba(74,222,128,.09),transparent);\n    border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin:18px 0 0;\n    font-size:13px;color:var(--muted)}\n  .banner b{color:var(--text)}\n  table.t{width:100%;border-collapse:collapse;font-family:var(--mono);font-size:12px;margin-top:10px}\n  table.t th{text-align:left;color:var(--muted);font-weight:500;padding:6px 8px;border-bottom:1px solid var(--line)}\n  table.t td{padding:6px 8px;border-bottom:1px solid #14211c}\n</style>\n</head>\n<body>\n<div class="wrap">\n\n<header>\n  <div class="logo">\n    <svg class="mark" viewBox="0 0 34 38" fill="none" aria-hidden="true">\n      <path d="M17 2 31 7v12c0 8-6 14-14 17C9 33 3 27 3 19V7L17 2Z" stroke="#4ade80" stroke-width="1.8"/>\n      <path d="M12 14h10l-10 10h10" stroke="#4ade80" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>\n    </svg>\n    <div>\n      <h1>Shield<span>Lint</span></h1>\n      <p class="tag">Offline privacy linting for Zcash. Privacy has no compile error — this is the compiler diagnostic.</p>\n    </div>\n  </div>\n  <nav class="nav">\n    <a href="https://github.com/ace-coderr/ShieldLint" target="_blank" rel="noopener">GitHub ↗</a>\n    <a href="https://github.com/ace-coderr/ShieldLint/blob/main/docs/rules.md" target="_blank" rel="noopener">Rules ↗</a>\n    <a href="/health" target="_blank" rel="noopener">API</a>\n  </nav>\n</header>\n\n<div class="banner">\n  <b>Nothing leaves your browser session.</b> The scanner is stateless: code is analysed in memory and discarded —\n  no accounts, no storage, no telemetry. Run the same engine locally with <code>git clone github.com/ace-coderr/ShieldLint &amp;&amp; pip install -e .</code>.\n</div>\n\n<div class="tabs" role="tablist">\n  <button class="tab" role="tab" aria-selected="true"  data-panel="scan">scan</button>\n  <button class="tab" role="tab" aria-selected="false" data-panel="address">decode address</button>\n  <button class="tab" role="tab" aria-selected="false" data-panel="uri">validate payment uri</button>\n  <button class="tab" role="tab" aria-selected="false" data-panel="rules">rules</button>\n</div>\n\n<!-- ---------------------------------------------------------------- SCAN -->\n<section class="panel on" id="panel-scan">\n  <div class="card">\n    <div class="row" style="justify-content:space-between">\n      <div style="flex:1;min-width:180px">\n        <label class="field" for="fname">File name (drives the lexer)</label>\n        <input type="text" id="fname" value="checkout.py" spellcheck="false">\n      </div>\n      <div style="display:flex;gap:8px;padding-top:22px">\n        <button class="btn ghost" id="load-leaky">Load leaky example</button>\n        <button class="btn ghost" id="load-fixed">Load fixed example</button>\n      </div>\n    </div>\n    <div style="margin-top:14px">\n      <label class="field" for="code">Source</label>\n      <textarea id="code" rows="14" spellcheck="false" placeholder="Paste a file, or load an example above…"></textarea>\n    </div>\n    <div class="row" style="margin-top:12px;justify-content:space-between">\n      <p class="hint" id="scan-hint">Supports Python, JS/TS, Rust, Go, Java, C/C++, Ruby, PHP, YAML, TOML…</p>\n      <button class="btn" id="do-scan">Scan for leaks</button>\n    </div>\n  </div>\n  <div class="out" id="scan-out"></div>\n</section>\n\n<!-- ------------------------------------------------------------- ADDRESS -->\n<section class="panel" id="panel-address">\n  <div class="card">\n    <label class="field" for="addr">Zcash address or viewing key</label>\n    <div class="row" style="margin-top:4px">\n      <input type="text" id="addr" spellcheck="false" style="flex:1;min-width:260px"\n             placeholder="u1… / zu1… / zs1… / t1… / uview1…">\n      <button class="btn" id="do-addr">Decode</button>\n    </div>\n    <p class="hint">Decodes ZIP 316 Unified Addresses (incl. F4Jumble), Sapling, transparent and Sprout.\n      Shows every receiver, the revision, the network and whether a sender can downgrade to transparent.</p>\n  </div>\n  <div class="out" id="addr-out"></div>\n</section>\n\n<!-- ----------------------------------------------------------------- URI -->\n<section class="panel" id="panel-uri">\n  <div class="card">\n    <label class="field" for="uri">ZIP 321 payment request</label>\n    <div class="row" style="margin-top:4px">\n      <input type="text" id="uri" spellcheck="false" style="flex:1;min-width:260px"\n             placeholder="zcash:zu1…?amount=0.5&memo=b3JkZXI6MQ">\n      <button class="btn" id="do-uri">Validate</button>\n    </div>\n    <p class="hint">Full ZIP 321 grammar and semantics: parameter indexes, base64url memos,\n      the 512-byte limit, amount formatting, <code>req-</code> parameters, memo-on-transparent, Sprout.</p>\n  </div>\n  <div class="out" id="uri-out"></div>\n</section>\n\n<!-- --------------------------------------------------------------- RULES -->\n<section class="panel" id="panel-rules">\n  <p class="hint" style="margin-bottom:12px">14 rules, each tied to a specification and shipped with a rationale.</p>\n  <div id="rules-out"></div>\n</section>\n\n<footer>\n  <div>ShieldLint 0.1.0 · MIT · built for ZECATHON 2026 (Core &amp; Tooling)</div>\n  <div><a href="https://github.com/ace-coderr/ShieldLint" target="_blank" rel="noopener">source</a> ·\n       <a href="https://github.com/ace-coderr/ShieldLint/blob/main/docs/design.md" target="_blank" rel="noopener">design</a></div>\n</footer>\n</div>\n\n<script>\n(function () {\n  const $ = (id) => document.getElementById(id);\n  const esc = (s) => String(s == null ? "" : s).replace(/[&<>"\']/g, c => (\n    { "&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;", "\'": "&#39;" }[c]));\n\n  /* tabs */\n  document.querySelectorAll(".tab").forEach(tab => {\n    tab.addEventListener("click", () => {\n      document.querySelectorAll(".tab").forEach(t => t.setAttribute("aria-selected", "false"));\n      tab.setAttribute("aria-selected", "true");\n      document.querySelectorAll(".panel").forEach(p => p.classList.remove("on"));\n      $("panel-" + tab.dataset.panel).classList.add("on");\n      if (tab.dataset.panel === "rules") loadRules();\n      history.replaceState(null, "", "#" + tab.dataset.panel);\n    });\n  });\n  const initial = (location.hash || "#scan").slice(1);\n  const first = document.querySelector(\'.tab[data-panel="\' + initial + \'"]\');\n  if (first) first.click();\n\n  async function post(url, body) {\n    const res = await fetch(url, {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify(body)\n    });\n    const data = await res.json().catch(() => ({}));\n    if (!res.ok) throw new Error(data.detail || ("HTTP " + res.status));\n    return data;\n  }\n\n  /* -------------------------------------------------------------- scan */\n  async function loadExample(kind) {\n    const data = await (await fetch("/api/examples/" + kind)).json();\n    $("code").value = data.content;\n    $("fname").value = kind === "rust" ? "lib.rs" : "checkout.py";\n    $("scan-out").innerHTML = "";\n  }\n  $("load-leaky").onclick = () => loadExample("leaky");\n  $("load-fixed").onclick = () => loadExample("fixed");\n\n  $("do-scan").onclick = async () => {\n    const content = $("code").value;\n    if (!content.trim()) { $("scan-out").innerHTML = \'<p class="hint bad">Paste some code first, or load an example.</p>\'; return; }\n    $("scan-out").innerHTML = \'<p class="hint"><span class="spin"></span> scanning…</p>\';\n    try {\n      const data = await post("/api/scan", { files: [{ name: $("fname").value, content }] });\n      const s = data.summary;\n      const total = data.findings.length;\n      let html = "";\n      if (total) {\n        html += \'<div class="card" style="border-color:#4a1f1f;background:linear-gradient(90deg,rgba(248,113,113,.07),transparent)">\' +\n          \'<div style="font-family:var(--mono);font-size:20px;font-weight:600">\' + total +\n          " leak" + (total === 1 ? "" : "s") + " found</div>" +\n          \'<div class="hint">\' + s.errors + " errors · " + s.warnings + " warnings · " +\n          Object.keys(s.by_rule).length + " distinct rules triggered</div></div>";\n      }\n      html += \'<div class="summary">\' +\n        \'<span class="pill">\' + s.files_scanned + " file" + (s.files_scanned === 1 ? "" : "s") + "</span>" +\n        \'<span class="pill \' + (s.errors ? "err" : "ok") + \'">\' + s.errors + " errors</span>" +\n        \'<span class="pill \' + (s.warnings ? "warn" : "") + \'">\' + s.warnings + " warnings</span>" +\n        "</div>";\n      if (!data.findings.length) {\n        html += \'<div class="finding" style="border-left-color:#4ade80"><div class="ftitle good">No findings — nothing to leak here.</div>\' +\n          \'<div class="fdetail">Shielded recipients, no memo or key exposure, valid payment URIs.</div></div>\';\n      } else {\n        html += data.findings.map(f =>\n          \'<div class="finding \' + esc(f.severity) + \'">\' +\n            \'<div class="fhead"><span class="rid">\' + esc(f.rule) + "</span>" +\n            \'<span class="sev \' + esc(f.severity) + \'">\' + esc(f.severity) + "</span>" +\n            \'<span class="rid">\' + esc(f.path) + ":" + f.line + ":" + f.column + "</span></div>" +\n            \'<div class="ftitle">\' + esc(f.message) + "</div>" +\n            (f.detail ? \'<div class="fdetail">\' + esc(f.detail) + "</div>" : "") +\n          "</div>").join("");\n      }\n      $("scan-out").innerHTML = html;\n    } catch (err) {\n      $("scan-out").innerHTML = \'<p class="hint bad">\' + esc(err.message) + "</p>";\n    }\n  };\n\n  /* ----------------------------------------------------------- address */\n  $("do-addr").onclick = async () => {\n    const value = $("addr").value.trim();\n    if (!value) return;\n    $("addr-out").innerHTML = \'<p class="hint"><span class="spin"></span> decoding…</p>\';\n    try {\n      const d = await post("/api/address", { value });\n      let html = \'<div class="card"><dl class="kv">\' +\n        "<dt>kind</dt><dd>" + esc(d.kind) + "</dd>" +\n        "<dt>network</dt><dd>" + esc(d.network) + "</dd>" +\n        (d.hrp ? "<dt>hrp</dt><dd>" + esc(d.hrp) + "</dd>" : "") +\n        (d.revision != null ? "<dt>revision</dt><dd>" + d.revision + "</dd>" : "") +\n        "<dt>shielded</dt><dd class=\'" + (d.shielded ? "good" : "bad") + "\'>" + (d.shielded ? "yes" : "no") + "</dd>" +\n        "<dt>receivers</dt><dd>" + (d.receivers.length\n          ? d.receivers.map(r => esc(r.name) + " <span style=\'color:#7a9087\'>(" + r.bytes + "B, " + esc(r.typecode) + ")</span>").join("<br>")\n          : "—") + "</dd>" +\n        (d.metadata.length ? "<dt>metadata</dt><dd>" + d.metadata.map(m => esc(m.kind) + " = " + m.value).join("<br>") + "</dd>" : "") +\n        "</dl>";\n      if (d.has_transparent_receiver) html += \'<p class="hint warnc">Contains a transparent receiver — a sender that cannot do shielded will downgrade to it, making the payment public.</p>\';\n      if (d.notes.length) html += \'<ul class="plain">\' + d.notes.map(n => "<li>" + esc(n) + "</li>").join("") + "</ul>";\n      if (d.errors.length) html += \'<ul class="plain">\' + d.errors.map(e => \'<li class="bad">\' + esc(e) + "</li>").join("") + "</ul>";\n      html += "</div>";\n      $("addr-out").innerHTML = html;\n    } catch (err) {\n      $("addr-out").innerHTML = \'<p class="hint bad">\' + esc(err.message) + "</p>";\n    }\n  };\n\n  /* --------------------------------------------------------------- uri */\n  $("do-uri").onclick = async () => {\n    const value = $("uri").value.trim();\n    if (!value) return;\n    $("uri-out").innerHTML = \'<p class="hint"><span class="spin"></span> validating…</p>\';\n    try {\n      const d = await post("/api/uri", { value });\n      let html = \'<div class="summary"><span class="pill \' + (d.ok ? "ok" : "err") + \'">\' + (d.ok ? "valid" : "invalid") + "</span></div>";\n      if (d.payments.length) {\n        html += \'<div class="card"><table class="t"><thead><tr><th>#</th><th>kind</th><th>amount</th><th>memo</th><th>exposure</th></tr></thead><tbody>\' +\n          d.payments.map(p => "<tr><td>" + esc(p.index || "—") + "</td><td>" + esc(p.kind) +\n            "</td><td>" + esc(p.amount || "—") + "</td><td>" + (p.memo_bytes ? p.memo_bytes + " B" : "—") +\n            "</td><td class=\'" + (p.transparent ? "bad" : "good") + "\'>" + (p.transparent ? "PUBLIC" : "shielded") + "</td></tr>").join("") +\n          "</tbody></table></div>";\n      }\n      if (d.errors.length) html += \'<ul class="plain">\' + d.errors.map(e => \'<li class="bad">\' + esc(e) + "</li>").join("") + "</ul>";\n      if (d.warnings.length) html += \'<ul class="plain">\' + d.warnings.map(w => \'<li class="warnc">\' + esc(w) + "</li>").join("") + "</ul>";\n      $("uri-out").innerHTML = html;\n    } catch (err) {\n      $("uri-out").innerHTML = \'<p class="hint bad">\' + esc(err.message) + "</p>";\n    }\n  };\n\n  /* ------------------------------------------------------------- rules */\n  let rulesLoaded = false;\n  async function loadRules() {\n    if (rulesLoaded) return;\n    const data = await (await fetch("/api/rules")).json();\n    const rows = data.rules.map(r => "<tr><td class=\'rid\'>" + esc(r.id) + "</td><td class=\'sev " +\n      esc(r.severity) + "\'>" + esc(r.severity) + "</td><td>" + esc(r.title) + "</td></tr>").join("");\n    $("rules-out").innerHTML =\n      \'<div class="card" style="margin-bottom:16px"><table class="t"><thead><tr><th>id</th><th>severity</th><th>check</th></tr></thead><tbody>\' +\n      rows + "</tbody></table></div>" +\n      data.rules.map(r =>\n      \'<div class="rule"><h3><span class="rid">\' + esc(r.id) + "</span> · " + esc(r.title) +\n      \' <span class="sev \' + esc(r.severity) + \'">\' + esc(r.severity) + "</span></h3>" +\n      "<p>" + esc(r.summary) + "</p>" +\n      "<p><span style=\'color:#9fb8ad\'>Why:</span> " + esc(r.rationale) + "</p>" +\n      "<p><span style=\'color:#9fb8ad\'>Fix:</span> " + esc(r.remediation) + "</p></div>").join("");\n    rulesLoaded = true;\n  }\n\n  /* preload the demo so a first-time visitor sees the product work */\n  loadExample("leaky").then(() => $("do-scan").click()).catch(() => {});\n})();\n</script>\n</body>\n</html>\n'
